def seed():
    Base.metadata.create_all(engine)
    _ensure_sqlite_columns()
    db = Session()
    try:
        t = db.query(Tenant).filter(Tenant.code == "crown").first()
        if not t:
            t = Tenant(code="crown", name="Crown Coffee", plan="pro")
            db.add(t)
            db.flush()

        b = db.query(Branch).filter(Branch.tenant_id == t.id).first()
        if not b:
            b = Branch(tenant_id=t.id, code="uttara", name="Crown Coffee Uttara", address="Sector 3, Uttara, Dhaka", phone="+8801700000000")
            db.add(b)
            db.flush()

        term = db.query(Terminal).filter(Terminal.tenant_id == t.id).first()
        if not term:
            term = Terminal(tenant_id=t.id, branch_id=b.id, code="POS-1", name="Main Counter POS")
            db.add(term)
            db.flush()

        owner = db.query(User).filter(User.tenant_id == t.id, User.emp_id == "1001").first()
        if not owner:
            owner = User(tenant_id=t.id, branch_id=b.id, emp_id="1001", name="Owner", role="owner", pw=hp("admin123"), pin="1234")
            manager = User(tenant_id=t.id, branch_id=b.id, emp_id="1002", name="Manager", role="manager", pw=hp("admin123"), pin="9999")
            cashier = User(tenant_id=t.id, branch_id=b.id, emp_id="1003", name="Cashier", role="cashier", pw=hp("admin123"), pin=None)
            db.add_all([owner, manager, cashier])
            db.flush()

        # Check if full Crown Coffee menu is already seeded
        existing_dish_count = db.query(Item).filter(Item.tenant_id == t.id).count()
        
        # Ensure user can manually input selling price without preset prices
        old_preset_prices = {39900, 44100, 46400, 41400, 25600, 21600, 42200, 45900, 56200, 49100, 63800, 51000, 62200, 44600, 46100, 56000, 25900, 39100, 18100, 59600, 40500, 48500, 70400, 19700, 21900, 23300, 26700, 34800, 8300, 53500}
        for item_obj in db.query(Item).filter(Item.tenant_id == t.id).all():
            if item_obj.price in old_preset_prices:
                item_obj.price = None
        db.flush()

        if existing_dish_count < 30:
            # Clear old demo items, recipes, ingredients if any to prevent duplicates
            db.query(RecipeItem).filter(RecipeItem.tenant_id == t.id).delete()
            db.query(Recipe).filter(Recipe.tenant_id == t.id).delete()
            db.query(Item).filter(Item.tenant_id == t.id).delete()
            db.query(InventoryBatchLine).filter(InventoryBatchLine.tenant_id == t.id).delete()
            db.query(StockLedger).filter(StockLedger.tenant_id == t.id).delete()
            db.query(InventoryBatch).filter(InventoryBatch.tenant_id == t.id).delete()
            db.query(Ingredient).filter(Ingredient.tenant_id == t.id).delete()
            db.flush()

            # Seed 31 Crown Coffee dishes
            created_items = {}
            for d in CROWN_ITEMS:
                it = Item(
                    tenant_id=t.id,
                    branch_id=b.id,
                    category=d["category"],
                    name=d["name"],
                    barcode=d["barcode"],
                    price=d["price"],
                    station=d["station"],
                )
                db.add(it)
                db.flush()
                created_items[d["name"]] = it

            # Seed ingredients
            created_ingredients = {}
            for ing in CROWN_INGREDIENTS:
                obj = Ingredient(
                    tenant_id=t.id,
                    barcode=ing["barcode"],
                    name=ing["name"],
                    unit=ing["unit"],
                    pack_size=ing["pack_size"],
                    pack_unit=ing["pack_unit"],
                    min_stock=ing["min_stock"],
                    current_stock=ing["current_stock"],
                    cost_per_unit=ing["cost_per_unit"],
                )
                db.add(obj)
                db.flush()
                created_ingredients[ing["name"].lower().strip()] = obj

            # Seed initial central inventory batch & stock ledger
            today = date.today().isoformat()
            central_batch = InventoryBatch(
                tenant_id=t.id,
                batch_type="central",
                batch_date=today,
                status="approved",
                note="Crown Coffee Master Opening Stock",
                created_by=owner.id,
                approved_by=owner.id,
            )
            db.add(central_batch)
            db.flush()

            for ing_obj in created_ingredients.values():
                db.add(InventoryBatchLine(
                    tenant_id=t.id,
                    batch_id=central_batch.id,
                    bazar_item_id=ing_obj.id,
                    quantity=ing_obj.current_stock,
                    pack_count=round(ing_obj.current_stock / (ing_obj.pack_size or 1), 2),
                ))
                db.add(StockLedger(
                    tenant_id=t.id,
                    bazar_item_id=ing_obj.id,
                    quantity=ing_obj.current_stock,
                    type="central",
                    batch_id=central_batch.id,
                    date=today,
                    reason="Opening Central Stock",
                    created_by=owner.id,
                ))

            # Seed approved recipes for all dishes
            for dish_name, lines_data in CROWN_RECIPES.items():
                item_obj = created_items.get(dish_name)
                if not item_obj:
                    continue
                rec = Recipe(
                    tenant_id=t.id,
                    item_id=item_obj.id,
                    version=1,
                    status="approved",
                    created_by=owner.id,
                    approved_by=owner.id,
                )
                db.add(rec)
                db.flush()
                for line in lines_data:
                    ing_obj = created_ingredients.get(line["ingredient"].lower().strip())
                    if not ing_obj:
                        continue
                    db.add(RecipeItem(
                        tenant_id=t.id,
                        recipe_id=rec.id,
                        item_id=item_obj.id,
                        ingredient_id=ing_obj.id,
                        qty=line["qty"],
                        input_amount=line["input_amount"],
                        input_unit=line["input_unit"],
                        version=1,
                    ))

        if not db.query(TableLayout).first():
            default_layout = [
                {"id": "T1", "label": "T1", "x": 40, "y": 40, "width": 80, "height": 80, "shape": "square"},
                {"id": "T2", "label": "T2", "x": 160, "y": 40, "width": 80, "height": 80, "shape": "square"},
                {"id": "T3", "label": "T3", "x": 280, "y": 40, "width": 80, "height": 80, "shape": "square"},
                {"id": "T4", "label": "T4", "x": 400, "y": 40, "width": 80, "height": 80, "shape": "square"},
                {"id": "T5", "label": "T5", "x": 40, "y": 160, "width": 80, "height": 80, "shape": "square"},
                {"id": "T6", "label": "T6", "x": 160, "y": 160, "width": 80, "height": 80, "shape": "square"},
                {"id": "T7", "label": "T7", "x": 280, "y": 160, "width": 80, "height": 80, "shape": "round"},
                {"id": "T8", "label": "T8", "x": 400, "y": 160, "width": 80, "height": 80, "shape": "round"},
            ]
            db.add(TableLayout(tenant_id=t.id, channel="dine_in", layout_json=json.dumps(default_layout)))

        db.commit()
    finally:
        db.close()
